ALL_GENRES = ['Action', 'Adventure', 'Comedy', 'Drama', 'Ecchi', 'Fantasy', 'Horror', 'Mahou Shoujo', 'Mecha', 'Music', 'Mystery', 'Psychological', 'Romance', 'Sci-Fi', 'Slice of Life', 'Sports', 'Supernatural', 'Thriller', 'Hentai']

class VectorizerService:
    @staticmethod
    def vectorize(anime):
        tags = getattr(anime, "tags", [])
        tag_dict = {tag.name: tag.rank for tag in tags} if tags else {}
        # Square the weight to heavily emphasize primary/defining tags (90%+) over minor tags (40%)
        tag_vector = [(tag_dict.get(t, 0.0) / 100.0) ** 2 for t in ALL_TAGS]
        
        genres = getattr(anime, "genres", []) or []
        # If tags are sparse (<7), use genres as a fallback with 33% weight
        genre_weight = 0.33 if len(tags) < 7 else 0.0
        genre_vector = [genre_weight if g in genres else 0.0 for g in ALL_GENRES]
        
        score_norm = (getattr(anime, "averageScore", 0) or 0) / 100.0
        pop_norm = min((getattr(anime, "popularity", 0) or 0) / 1000000.0, 1.0)
        
        # Combine tags, genres, and numeric metrics
        vector = tag_vector + genre_vector + [score_norm, pop_norm]
        return vector
